extends SceneTree

func _initialize() -> void:
	var n := (load("res://assets/models/keeper_house.glb") as PackedScene).instantiate() as Node3D
	root.add_child(n)
	for mi in n.find_children("*", "MeshInstance3D", true, false):
		var m := mi as MeshInstance3D
		print("MESH %s aabb=%s surfaces=%d" % [m.name, m.get_aabb(), m.mesh.get_surface_count()])
		for s in m.mesh.get_surface_count():
			var mat := m.mesh.surface_get_material(s)
			var arr := m.mesh.surface_get_arrays(s)
			var v: PackedVector3Array = arr[Mesh.ARRAY_VERTEX]
			var lo := 1e9
			var hi := -1e9
			for p in v:
				lo = minf(lo, p.y)
				hi = maxf(hi, p.y)
			print("  surf %d mat=%s verts=%d y=[%.2f, %.2f]" % [s, mat.resource_name if mat else "-", v.size(), lo, hi])
			if mat is BaseMaterial3D:
				print("   tex=%s col=%s" % [(mat as BaseMaterial3D).albedo_texture, (mat as BaseMaterial3D).albedo_color])
	quit(0)

