shader_type spatial;
render_mode cull_disabled;
// Копия материала дома (роспись атласом / контур-оболочка) с дизерным растворением верха:
// кровля (выше cut.x) и навес (выше cut.y и дальше cut.z от центра, т. е. перед стеной) — только они.
// Координаты cut — в пространстве меша (до масштаба узла). fade 0..1 — доля отброшенных пикселей.

uniform sampler2D albedo_tex : source_color, filter_nearest_mipmap, repeat_enable;
uniform vec4 albedo : source_color = vec4(1.0);
uniform vec3 emission = vec3(0.0);
uniform float metallic = 0.0;
uniform float roughness = 1.0;
uniform bool back_cull = false;
uniform vec3 cut = vec3(1000.0, 1000.0, 1000.0);
uniform float fade = 0.0;

varying vec3 lpos;

const float BAYER[16] = float[16](0.0, 8.0, 2.0, 10.0, 12.0, 4.0, 14.0, 6.0, 3.0, 11.0, 1.0, 9.0, 15.0, 7.0, 13.0, 5.0);

void vertex() {
	lpos = VERTEX;
}

void fragment() {
	if (back_cull && !FRONT_FACING) {
		discard;
	}
	bool top = lpos.y > cut.x || (lpos.y > cut.y && lpos.z > cut.z);
	if (top) {
		ivec2 p = ivec2(FRAGCOORD.xy) % 4;
		if ((BAYER[p.y * 4 + p.x] + 0.5) / 16.0 <= fade) {
			discard;
		}
	}
	ALBEDO = texture(albedo_tex, UV).rgb * albedo.rgb;
	METALLIC = metallic;
	ROUGHNESS = roughness;
	EMISSION = emission;
}

